const PDFIUM_UI_LANGUAGE_AUTO = 'auto';
const PDFIUM_UI_LANGUAGE_ENGLISH = 'en';
const PDFIUM_UI_LANGUAGE_NORWEGIAN_BOKMAL = 'nb';
const PDFIUM_UI_LANGUAGE_GERMAN = 'de';
const PDFIUM_UI_LANGUAGE_SPANISH = 'es';
const PDFIUM_UI_LANGUAGE_SWEDISH = 'sv';
const PDFIUM_UI_LANGUAGE_DANISH = 'da';
const PDFIUM_UI_LANGUAGE_FRENCH = 'fr';
const PDFIUM_UI_LANGUAGE_CODES = Object.freeze([
  PDFIUM_UI_LANGUAGE_ENGLISH,
  PDFIUM_UI_LANGUAGE_NORWEGIAN_BOKMAL,
  PDFIUM_UI_LANGUAGE_GERMAN,
  PDFIUM_UI_LANGUAGE_SPANISH,
  PDFIUM_UI_LANGUAGE_SWEDISH,
  PDFIUM_UI_LANGUAGE_DANISH,
  PDFIUM_UI_LANGUAGE_FRENCH
]);
const PDFIUM_UI_LANGUAGES = Object.freeze([
  PDFIUM_UI_LANGUAGE_AUTO,
  ...PDFIUM_UI_LANGUAGE_CODES
]);
const PDFIUM_UI_LANGUAGE_LABELS = Object.freeze({
  en:'English',
  nb:'Norsk bokmål',
  de:'Deutsch',
  es:'Español',
  sv:'Svenska',
  da:'Dansk',
  fr:'Français'
});

function pdfiumNormalizeLanguageCode(value) {
  const raw=String(value || '').trim().replace('_','-');
  const lower=raw.toLowerCase();
  if(lower==='nb' || lower.startsWith('nb-') || lower==='no' || lower.startsWith('no-')) return PDFIUM_UI_LANGUAGE_NORWEGIAN_BOKMAL;
  const base=lower.split('-')[0];
  return PDFIUM_UI_LANGUAGE_CODES.includes(base) ? base : PDFIUM_UI_LANGUAGE_ENGLISH;
}

function pdfiumNormalizeLanguageSetting(value) {
  const raw=String(value || '').trim().toLowerCase();
  return PDFIUM_UI_LANGUAGES.includes(raw) ? raw : PDFIUM_UI_LANGUAGE_AUTO;
}

function pdfiumReadObsidianLanguage(obsidianApi, windowObject) {
  try {
    if(obsidianApi && typeof obsidianApi.getLanguage === 'function') {
      const resolved=obsidianApi.getLanguage();
      if(resolved) return String(resolved);
    }
  } catch (_) {}

  // Compatibility fallback is intentionally isolated here. It is not a production
  // dependency for any other feature and can be replaced if Obsidian changes its API.
  try {
    const stored=windowObject?.localStorage?.getItem?.('language');
    if(stored) return String(stored);
  } catch (_) {}

  try {
    const browserLanguage=windowObject?.navigator?.language;
    if(browserLanguage) return String(browserLanguage);
  } catch (_) {}
  return PDFIUM_UI_LANGUAGE_ENGLISH;
}

function pdfiumResolveUiLanguage(requestedLanguage, obsidianApi, windowObject) {
  const requested=pdfiumNormalizeLanguageSetting(requestedLanguage);
  if(requested!==PDFIUM_UI_LANGUAGE_AUTO) return requested;
  return pdfiumNormalizeLanguageCode(pdfiumReadObsidianLanguage(obsidianApi,windowObject));
}

function pdfiumTranslationPlaceholders(text) {
  return [...String(text || '').matchAll(/\{\{([a-zA-Z0-9_]+)\}\}/g)].map(match=>match[1]);
}

function pdfiumInterpolateTranslation(template, params = {}) {
  return String(template || '').replace(/\{\{([a-zA-Z0-9_]+)\}\}/g, (_match,key) => {
    return Object.prototype.hasOwnProperty.call(params,key) ? String(params[key]) : `{{${key}}}`;
  });
}

function createPdfiumI18n({ requestedLanguage='auto', obsidianApi=null, windowObject=null, translations={} } = {}) {
  let requested=pdfiumNormalizeLanguageSetting(requestedLanguage);
  const dictionaries=Object.create(null);
  for(const [locale,dictionary] of Object.entries(translations || {})) {
    if(dictionary && typeof dictionary==='object' && !Array.isArray(dictionary)) dictionaries[String(locale)]=dictionary;
  }
  const english=dictionaries.en || {};

  function resolvedLanguage() {
    return pdfiumResolveUiLanguage(requested,obsidianApi,windowObject);
  }

  function translate(key, params = {}) {
    const translationKey=String(key || '');
    const language=resolvedLanguage();
    const dictionary=dictionaries[language] || english;
    const template=Object.prototype.hasOwnProperty.call(dictionary,translationKey)
      ? dictionary[translationKey]
      : (Object.prototype.hasOwnProperty.call(english,translationKey) ? english[translationKey] : translationKey);
    return pdfiumInterpolateTranslation(template,params);
  }

  return Object.freeze({
    t:translate,
    getRequestedLanguage(){ return requested; },
    getResolvedLanguage:resolvedLanguage,
    setRequestedLanguage(value){ requested=pdfiumNormalizeLanguageSetting(value); return resolvedLanguage(); },
    hasKey(key){ return Object.prototype.hasOwnProperty.call(english,String(key || '')); }
  });
}

function pdfiumTranslateMetadataValidationMessage(i18n, message) {
  const t=(key,params)=>i18n?.t?.(key,params) || String(message || '');
  const raw=String(message || '').trim();
  if(!raw) return raw;
  const lower=raw.toLowerCase();
  const exact=new Map([
    ['feltet er påkrevd','validation.required'],
    ['velg minst én verdi','validation.multiselectRequired'],
    ['forventet heltall','validation.expectedInteger'],
    ['ugyldig desimaltall','validation.invalidDecimal'],
    ['time må være mellom 1 og 12','validation.hour12Range']
  ]);
  if(exact.has(lower)) return t(exact.get(lower));

  let match=/^forventet datoformat\s+(.+)$/i.exec(raw);
  if(match) return t('validation.expectedDateFormat',{format:match[1]});
  match=/^forventet tidsformat\s+(.+)$/i.exec(raw);
  if(match) return t('validation.expectedTimeFormat',{format:match[1]});
  match=/^forventet desimaltall med\s+(punktum|komma)$/i.exec(raw);
  if(match) {
    const separatorName=t(match[1].toLowerCase()==='punktum'?'validation.separator.dot':'validation.separator.comma');
    return t('validation.expectedDecimalSeparator',{separatorName});
  }
  match=/^ukjent felttype\s+(.+)$/i.exec(raw);
  if(match) return t('validation.unknownFieldType',{type:match[1]});

  const canonicalSuffixes=[
    [': must be string','validation.mustBeString'],
    [': shorter than min_length','validation.shorterThanMinimum'],
    [': longer than max_length','validation.longerThanMaximum'],
    [': invalid canonical date','validation.invalidDate'],
    [': outside date range','validation.outsideDateRange'],
    [': invalid canonical time','validation.invalidTime'],
    [': outside time range','validation.outsideTimeRange'],
    [': must be integer','validation.mustBeInteger'],
    [': outside numeric range','validation.outsideNumericRange'],
    [': must be finite number','validation.mustBeFiniteNumber'],
    [': must be boolean','validation.mustBeBoolean'],
    [': must be option value string','validation.mustBeOptionValue'],
    [': option does not exist','validation.optionMissing'],
    [': must be string array','validation.mustBeStringArray'],
    [': duplicate values','validation.duplicateValues'],
    [': fewer than min_items','validation.tooFewItems'],
    [': more than max_items','validation.tooManyItems'],
    [': must be non-empty string','validation.mustBeNonEmptyString']
  ];
  for(const [suffix,key] of canonicalSuffixes) if(lower.endsWith(suffix)) return t(key);
  match=/: option\s+(.+)\s+does not exist$/i.exec(raw);
  if(match) return t('validation.optionDoesNotExist',{value:match[1]});
  return raw;
}

// Canonical Main Bridge -> renderer event contract. Production actions travel
// only through these explicit events; diagnostics may mirror state but must not
// be used as a production transport.
const RENDERER_BRIDGE_EVENTS = Object.freeze({
  OBSIDIAN_COMMAND: 'pdfium-gate-obsidian-command',
  KEYBOARD_SELECTION: 'pdfium-gate-pdf-keyboard-selection',
  NATIVE_COPY: 'pdfium-gate-native-copy',
  KEYBOARD_COPY: 'pdfium-gate-keyboard-copy',
  PDF_CONTEXT_MENU: 'pdfium-gate-pdf-context-menu',
  CATEGORY_SHORTCUT: 'pdfium-gate-category-shortcut',
  ESCAPE_DISMISS: 'pdfium-gate-escape-dismiss',
  PDF_MOUSE_ACTIVATION: 'pdfium-gate-pdf-mouse-activation'
});

const RENDERER_BRIDGE_EVENT_NAMES = new Set(Object.values(RENDERER_BRIDGE_EVENTS));

function validateRendererBridgeEventDetail(eventName, detail) {
  const name=String(eventName||'');
  if(!RENDERER_BRIDGE_EVENT_NAMES.has(name)) return {ok:false,error:`ukjent renderer bridge-event: ${name}`};
  if(!detail || typeof detail!=='object' || Array.isArray(detail)) return {ok:false,error:`${name}: detail må være et objekt`};
  const token=String(detail.token||detail.keyboardSelectionState?.token||'').trim();
  const text=String(detail.selectedText||detail.keyboardSelectionState?.text||'');
  const finite=value=>Number.isFinite(Number(value));
  if(name===RENDERER_BRIDGE_EVENTS.OBSIDIAN_COMMAND && !String(detail.commandId||'').trim()) return {ok:false,error:'obsidian-command: commandId mangler'};
  if(name===RENDERER_BRIDGE_EVENTS.KEYBOARD_SELECTION && (!token || !String(detail.direction||'').trim())) return {ok:false,error:'keyboard-selection: token/direction mangler'};
  if((name===RENDERER_BRIDGE_EVENTS.NATIVE_COPY || name===RENDERER_BRIDGE_EVENTS.KEYBOARD_COPY) && (!token || !text)) return {ok:false,error:'copy-event: token/selectedText mangler'};
  if(name===RENDERER_BRIDGE_EVENTS.PDF_CONTEXT_MENU && (detail.isPdfContext!==true || !String(detail.token||'').trim())) return {ok:false,error:'pdf-context-menu: isPdfContext/token mangler'};
  if(name===RENDERER_BRIDGE_EVENTS.CATEGORY_SHORTCUT && (!String(detail.id||'').trim() || !finite(detail.resultSeq))) return {ok:false,error:'category-shortcut: id/resultSeq mangler'};
  if(name===RENDERER_BRIDGE_EVENTS.ESCAPE_DISMISS && !finite(detail.dismissSeq)) return {ok:false,error:'escape-dismiss: dismissSeq mangler'};
  if(name===RENDERER_BRIDGE_EVENTS.PDF_MOUSE_ACTIVATION && (!String(detail.token||'').trim() || !finite(detail.activationSeq))) return {ok:false,error:'pdf-mouse-activation: token/activationSeq mangler'};
  return {ok:true,detail};
}

function readRendererBridgeEventDetail(eventName, event) {
  const detail=event && event.detail && typeof event.detail==='object' ? event.detail : null;
  return validateRendererBridgeEventDetail(eventName,detail);
}

// Canonical parent <-> annotator request/result contract. Both the renderer
// transport and generated annotator runtime consume this same source at build
// time so message names and response policies cannot drift independently.
const ANNOTATOR_MESSAGE_CONTRACTS = Object.freeze({
  'prewarm-keyboard-model':Object.freeze({resultType:'prewarm-keyboard-model-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd ved keyboard-model prewarm.',failureMessage:'Keyboard-model prewarm feilet.',responsePolicy:'ok'}),
  'keyboard-expand-selection':Object.freeze({resultType:'keyboard-expand-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium utvidet tastatur-selection.',failureMessage:'Keyboard-selection kunne ikke utvides.',responsePolicy:'ok'}),
  'filter-selection-artifacts':Object.freeze({resultType:'filter-selection-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium filtrerte topp-/bunntekst.',failureMessage:'Artifact-filter feilet.',responsePolicy:'ok'}),
  'find-selection':Object.freeze({resultType:'selection-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium søkte etter markert tekst.',failureMessage:'Selection-søk feilet.',responsePolicy:'ok'}),
  'inspect-point-highlights':Object.freeze({resultType:'inspect-point-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium hit-testet eksisterende highlights.',failureMessage:'Highlight hit-test feilet.',responsePolicy:'ok'}),
  'inspect-selection-highlights':Object.freeze({resultType:'inspect-selection-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium kontrollerte eksisterende highlights.',failureMessage:'Highlight-inspeksjon feilet.',responsePolicy:'ok'}),
  'read-existing-highlight-selection':Object.freeze({resultType:'read-highlight-selection-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium leste kategori-markeringen.',failureMessage:'Kunne ikke lese kategori-markeringen.',responsePolicy:'ok'}),
  'modify-existing-highlight':Object.freeze({resultType:'modify-highlight-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium endret eksisterende highlight.',failureMessage:'Kunne ikke endre eksisterende highlight.',responsePolicy:'ok-pdf-buffer'}),
  'write-selection-highlight':Object.freeze({resultType:'write-selection-result',timeoutMs:90000,timeoutMessage:'Tidsavbrudd mens PDFium skrev selection-highlight.',failureMessage:'Selection-highlight kunne ikke skrives.',responsePolicy:'allow-result'}),
  'write-highlight':Object.freeze({resultType:'write-result',timeoutMs:60000,timeoutMessage:'Tidsavbrudd mens PDFium skrev annotasjonen.',failureMessage:'Ukjent annotasjonsfeil.',responsePolicy:'ok-pdf-buffer'})
});

function getAnnotatorMessageContract(type) {
  return ANNOTATOR_MESSAGE_CONTRACTS[String(type||'')]||null;
}

function isAnnotatorRequestType(type) {
  return !!getAnnotatorMessageContract(type);
}

// PDFium Gate Platform Contract — exact open PDF leaf identity + activation.
// Source-of-truth for the adapter bundled into release main.js.
const PDF_LEAF_CONTRACT_VERSION = '0.5';

function createPdfLeafAdapter({ workspace, viewType }) {
  if (!workspace || typeof workspace.getLeavesOfType !== 'function') {
    throw new Error('workspace.getLeavesOfType er ikke tilgjengelig');
  }
  const safeViewType = String(viewType || '').trim();
  if (!safeViewType) throw new Error('viewType mangler');

  function leafFilePath(leaf) {
    try {
      const loadedPath = leaf?.view?.file?.path;
      if (loadedPath) return String(loadedPath);
    } catch (_) {}
    // Background tabs may be DeferredView since Obsidian 1.7.2. Match on the
    // public view state as well, so exact identity does not depend on the tab
    // already being visible/loaded.
    try {
      const state = typeof leaf?.getViewState === 'function' ? leaf.getViewState() : null;
      const statePath = state?.state?.file;
      if (state?.type === safeViewType && statePath) return String(statePath);
    } catch (_) {}
    return null;
  }

  function leafPdfToken(leaf) {
    // Token identity exists only on a loaded PDFium view. That is intentional:
    // this route is used only after a physical mouse event arrived from the
    // already-running embedded Chromium PDF frame.
    try {
      const view = leaf?.view || null;
      if (!view || typeof view.getViewType !== 'function' || view.getViewType() !== safeViewType) return null;
      return String(view.pdfToken || '').trim() || null;
    } catch (_) {
      return null;
    }
  }

  function enumerateLeaves(reasonTarget) {
    try { return { ok:true, leaves:workspace.getLeavesOfType(safeViewType) || [], error:null }; }
    catch (error) {
      return { ok:false, leaves:[], error:error instanceof Error ? error.message : String(error), reasonTarget };
    }
  }

  function getActiveLeaf() {
    try { return { ok:true, leaf:workspace.activeLeaf || null, error:null }; }
    catch (error) {
      return { ok:false, leaf:null, error:error instanceof Error ? error.message : String(error) };
    }
  }

  function listOpenLeaves() {
    const result = enumerateLeaves('list-open-pdf-leaves');
    return result.ok
      ? { ok:true, leaves:result.leaves, error:null }
      : { ok:false, leaves:[], error:result.error };
  }

  function resolveExact(filePath) {
    const targetPath = String(filePath || '').trim();
    if (!targetPath) {
      return { ok:false, filePath:null, leaf:null, reason:'missing-file-path', matchCount:0, candidateCount:0, error:'PDF-filsti mangler' };
    }
    const enumeration = enumerateLeaves(targetPath);
    if (!enumeration.ok) {
      return { ok:false, filePath:targetPath, leaf:null, reason:'enumeration-failed', matchCount:0, candidateCount:0, error:enumeration.error };
    }
    const leaves = enumeration.leaves;
    const matches = leaves.filter(leaf => leafFilePath(leaf) === targetPath);
    if (matches.length === 1) {
      return { ok:true, filePath:targetPath, leaf:matches[0], reason:'exact-file-path', matchCount:1, candidateCount:leaves.length, error:null };
    }
    if (matches.length === 0) {
      return { ok:false, filePath:targetPath, leaf:null, reason:'not-found', matchCount:0, candidateCount:leaves.length, error:'Eksakt åpen PDFium-fane ble ikke funnet' };
    }
    return { ok:false, filePath:targetPath, leaf:null, reason:'ambiguous', matchCount:matches.length, candidateCount:leaves.length, error:'Flere åpne PDFium-faner matcher samme filsti' };
  }

  function resolveExactToken(pdfToken) {
    const targetToken = String(pdfToken || '').trim();
    if (!targetToken) {
      return { ok:false, token:null, leaf:null, reason:'missing-token', matchCount:0, candidateCount:0, error:'PDF-token mangler' };
    }
    const enumeration = enumerateLeaves(targetToken);
    if (!enumeration.ok) {
      return { ok:false, token:targetToken, leaf:null, reason:'enumeration-failed', matchCount:0, candidateCount:0, error:enumeration.error };
    }
    const leaves = enumeration.leaves;
    const matches = leaves.filter(leaf => leafPdfToken(leaf) === targetToken);
    if (matches.length === 1) {
      return { ok:true, token:targetToken, leaf:matches[0], reason:'exact-loaded-token', matchCount:1, candidateCount:leaves.length, error:null };
    }
    if (matches.length === 0) {
      return { ok:false, token:targetToken, leaf:null, reason:'not-found', matchCount:0, candidateCount:leaves.length, error:'Eksakt lastet PDFium-fane for PDF-token ble ikke funnet' };
    }
    return { ok:false, token:targetToken, leaf:null, reason:'ambiguous', matchCount:matches.length, candidateCount:leaves.length, error:'Flere lastede PDFium-faner matcher samme PDF-token' };
  }

  function activateExactToken(pdfToken) {
    const resolved = resolveExactToken(pdfToken);
    if (!resolved.ok) return { ...resolved, activated:false };
    if (typeof workspace.setActiveLeaf !== 'function') {
      return { ...resolved, ok:false, activated:false, reason:'activate-unavailable', error:'workspace.setActiveLeaf er ikke tilgjengelig' };
    }
    try {
      // A physical click has already placed input focus inside the Chromium PDF
      // iframe. Change only Obsidian's active-leaf identity; do not steal focus
      // back out of the iframe.
      workspace.setActiveLeaf(resolved.leaf, { focus:false });
      return { ...resolved, activated:true };
    } catch (error) {
      return { ...resolved, ok:false, activated:false, reason:'activate-failed', error:error instanceof Error ? error.message : String(error) };
    }
  }

  async function revealAndActivateExact(filePath) {
    const resolved = resolveExact(filePath);
    if (!resolved.ok) return { ...resolved, revealed:false, activated:false };
    if (typeof workspace.revealLeaf !== 'function') {
      return { ...resolved, ok:false, revealed:false, activated:false, reason:'reveal-unavailable', error:'workspace.revealLeaf er ikke tilgjengelig' };
    }
    if (typeof workspace.setActiveLeaf !== 'function') {
      return { ...resolved, ok:false, revealed:false, activated:false, reason:'activate-unavailable', error:'workspace.setActiveLeaf er ikke tilgjengelig' };
    }
    try {
      await workspace.revealLeaf(resolved.leaf);
    } catch (error) {
      return { ...resolved, ok:false, revealed:false, activated:false, reason:'reveal-failed', error:error instanceof Error ? error.message : String(error) };
    }
    try {
      workspace.setActiveLeaf(resolved.leaf, { focus:true });
      return { ...resolved, revealed:true, activated:true };
    } catch (error) {
      return { ...resolved, ok:false, revealed:true, activated:false, reason:'activate-failed', error:error instanceof Error ? error.message : String(error) };
    }
  }

  function acquireOpenTarget(requestedNewLeaf = false) {
    const wantNewLeaf = !!requestedNewLeaf;
    const mode = wantNewLeaf ? 'tab' : false;
    if (typeof workspace.getLeaf !== 'function') {
      return {
        ok:false, leaf:null, requestedNewLeaf:wantNewLeaf, mode, reason:'get-leaf-unavailable',
        error:'workspace.getLeaf er ikke tilgjengelig'
      };
    }
    let leaf = null;
    try { leaf = workspace.getLeaf(mode); }
    catch (error) {
      return {
        ok:false, leaf:null, requestedNewLeaf:wantNewLeaf, mode, reason:'get-leaf-failed',
        error:error instanceof Error ? error.message : String(error)
      };
    }
    if (!leaf || typeof leaf.openFile !== 'function') {
      return {
        ok:false, leaf:null, requestedNewLeaf:wantNewLeaf, mode, reason:'invalid-leaf',
        error:'workspace.getLeaf returnerte ikke en gyldig WorkspaceLeaf med openFile()'
      };
    }
    return { ok:true, leaf, requestedNewLeaf:wantNewLeaf, mode, reason:'workspace-get-leaf', error:null };
  }

  return Object.freeze({
    contractVersion: PDF_LEAF_CONTRACT_VERSION,
    leafFilePath,
    leafPdfToken,
    getActiveLeaf,
    listOpenLeaves,
    resolveExact,
    resolveExactToken,
    activateExactToken,
    acquireOpenTarget,
    revealAndActivateExact
  });
}

// PDFium Gate Platform Contract — renderer-side exact Obsidian command execution.
// The caller supplies one explicit command id. No alias, focused-view, keyboard,
// or alternate-command fallback is performed here.
const OBSIDIAN_COMMAND_EXECUTION_CONTRACT_VERSION = '0.1';

function createObsidianCommandExecutionAdapter({ commands }) {
  function executeExact(commandId) {
    const id = String(commandId || '').trim();
    if (!id) {
      return {
        ok:false, executed:false, commandId:null, result:null,
        reason:'missing-command-id', error:'Obsidian commandId mangler'
      };
    }
    if (!commands || typeof commands.executeCommandById !== 'function') {
      return {
        ok:false, executed:false, commandId:id, result:null,
        reason:'execute-unavailable', error:'commands.executeCommandById er ikke tilgjengelig'
      };
    }
    try {
      const raw = commands.executeCommandById(id);
      const result = raw === undefined ? null : !!raw;
      if (raw === false) {
        return {
          ok:false, executed:false, commandId:id, result:false,
          reason:'command-returned-false', error:null
        };
      }
      return {
        ok:true, executed:true, commandId:id, result,
        reason:'execute-command-by-id', error:null
      };
    } catch (error) {
      return {
        ok:false, executed:false, commandId:id, result:null,
        reason:'execute-failed', error:error instanceof Error ? error.message : String(error)
      };
    }
  }

  return Object.freeze({
    contractVersion: OBSIDIAN_COMMAND_EXECUTION_CONTRACT_VERSION,
    executeExact
  });
}

// PDFium Gate Platform Contract — renderer Obsidian openLinkText hook lifecycle.
// The source file is canonical/documentary; release runtime bundles this adapter into main.js.
const OBSIDIAN_OPEN_LINK_HOOK_CONTRACT_VERSION = '0.1';

function createObsidianOpenLinkHookAdapter({ workspace }) {
  let originalOpenLinkText = null;
  let hook = null;
  let installed = false;

  function install(intercept) {
    if (!workspace || typeof workspace.openLinkText !== 'function') {
      return {
        ok:false, installed:false, reason:'open-link-unavailable',
        error:'workspace.openLinkText er ikke tilgjengelig'
      };
    }
    if (typeof intercept !== 'function') {
      return {
        ok:false, installed:false, reason:'invalid-interceptor',
        error:'openLinkText interceptor må være en funksjon'
      };
    }
    if (installed) {
      return {
        ok:false, installed:true, reason:'already-installed',
        error:'openLinkText hook er allerede installert'
      };
    }

    originalOpenLinkText = workspace.openLinkText;
    hook = async function(linktext, sourcePath, newLeaf, openViewState) {
      const handled = await intercept(linktext, sourcePath, newLeaf, openViewState);
      if (handled) return;
      return originalOpenLinkText.call(workspace, linktext, sourcePath, newLeaf, openViewState);
    };

    try {
      workspace.openLinkText = hook;
    } catch (error) {
      originalOpenLinkText = null;
      hook = null;
      return {
        ok:false, installed:false, reason:'install-failed',
        error:error instanceof Error ? error.message : String(error)
      };
    }

    if (workspace.openLinkText !== hook) {
      originalOpenLinkText = null;
      hook = null;
      return {
        ok:false, installed:false, reason:'install-not-retained',
        error:'workspace.openLinkText beholdt ikke installert hook'
      };
    }

    installed = true;
    return { ok:true, installed:true, reason:'exact-open-link-hook', error:null };
  }

  function restore() {
    if (!installed) {
      return { ok:true, restored:false, reason:'not-installed', error:null };
    }
    if (!workspace || workspace.openLinkText !== hook) {
      return {
        ok:false, restored:false, reason:'hook-replaced',
        error:'workspace.openLinkText peker ikke lenger på PDFium Gate-hooken'
      };
    }
    try {
      workspace.openLinkText = originalOpenLinkText;
    } catch (error) {
      return {
        ok:false, restored:false, reason:'restore-failed',
        error:error instanceof Error ? error.message : String(error)
      };
    }
    installed = false;
    originalOpenLinkText = null;
    hook = null;
    return { ok:true, restored:true, reason:'original-restored', error:null };
  }

  function getState() {
    return {
      installed,
      ownsCurrentHook:!!(installed && workspace && workspace.openLinkText === hook)
    };
  }

  return Object.freeze({
    contractVersion: OBSIDIAN_OPEN_LINK_HOOK_CONTRACT_VERSION,
    install,
    restore,
    getState
  });
}

