  for (let i = 0; i < raw.length; i += 1) {
    const ch = raw[i];
    if (isObsidianLinkIgnorableChar(ch)) continue;
    if (/\s/.test(ch)) {
      if (out && !lastSpace) { out += ' '; lastSpace = true; }
      continue;
    }
    out += ch;
    lastSpace = false;
  }
